  AvgDialog_13056_Content_31 = {
    Text = "...เฟอร์......"
  },
  AvgDialog_13056_Content_33 = {
    Text = "กล้ามเนื้อทุกมัดถูกควบคุมด้วยอะดรีนาลีน ทำให้เขาคว้าหอกขึ้นมาอย่างฉับพลัน แล้วพุ่งเข้าชนศัตรู!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:อย่าแตะต้องเขา!>"
