  AvgDialog_15365_Content_48 = {
    Text = "สวยงาม จริงไหม?\nพวกเขาเรียกฉันว่า “คนขายเนื้อ” เพราะฉันปฏิบัติต่อนายแบบอย่างโหดเหี้ยมไร้ปรานีเสมอ"
  },
  AvgDialog_15365_Content_49 = {
